{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "진통제 처방 용량이 의심스러운 상황에서 투약 전 재확인이 필요하다고 판단한 근거를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 환자의 진통제 용량이 평소의 두 배로 처방된 상황",
          "task": "처방대로 투약하기 전에 용량의 적절성을 판단해야 했음",
          "action": "당시 처방을 의심하게 만든 비교 정보와 용량 차이를 설명함",
          "result": "그 정보를 근거로 투약 전 담당의 확인이 필요하다고 판단함"
        },
        "expectedEvidence": [
          "투약 전 담당의 확인이 필요하다고 판단한 구체적인 근거",
          "평소 용량과 비교할 때 실제로 참고한 정보",
          "비교한 정보에서 발견한 처방 용량의 차이"
        ]
      },
      "question": "수술 후 환자의 진통제 용량이 평소의 두 배로 처방됐던 상황에서, 투약 전에 담당의 확인이 필요하다고 판단한 근거는 무엇이었나요?",
      "answerTip": "당시 직접 확인한 사실을 중심으로 짧게 답해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "진통제 처방이 평소의 두 배였다는 설명을 넘어, 당시 실제로 참고한 비교 정보와 그에 비추어 의심한 용량 차이를 구체적으로 제시한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "진통제 처방 용량이 평소보다 많았거나 환자 안전이 우려됐다는 일반적인 근거만 제시한다."
          ]
        },
        "poor": {
          "criteria": [
            "진통제 처방을 재확인해야 한다고 판단한 근거를 제시하지 않거나, 투약 중단 이후의 조치만 설명한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "낙상 위험이 있는 환자의 상태를 다음 근무자에게 빠짐없이 전달하기 위해 중요하게 선택한 정보가 무엇인지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 첫 보행 환자의 낙상이 근무 교대 시간대에 몰려 인수인계 체크리스트를 개선한 상황",
          "task": "다음 근무자에게 빠짐없이 전달할 환자 정보를 정해야 했음",
          "action": "인수인계에서 중요하게 전달하려던 환자 정보를 구체적으로 설명함",
          "result": "선택한 정보가 인수인계 체크리스트 항목으로 구체화됨"
        },
        "expectedEvidence": [
          "다음 근무자에게 빠짐없이 전달해야 한다고 선택한 환자 정보",
          "선택한 정보에 포함되는 구체적인 시점이나 환자 상태"
        ]
      },
      "question": "낙상 고위험 환자 인수인계 체크리스트를 개선할 때, 다음 근무자에게 가장 빠짐없이 전달해야 한다고 본 환자 정보는 무엇이었나요?",
      "answerTip": "핵심을 먼저 말한 뒤 구체적인 예를 짧게 덧붙여 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "인수인계 체크리스트의 항목명만 반복하지 않고, 마지막 진통제 투여 시점이나 보행 보조가 필요한 상태 등 다음 근무자에게 전달하려던 환자 정보를 구체적으로 제시한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "인수인계에서 진통제 투여 시각이나 보행 보조 여부가 중요하다고 말하지만, 항목명 수준을 넘어 전달 정보의 내용을 구체화하지 않는다."
          ]
        },
        "poor": {
          "criteria": [
            "인수인계에서 전달하려던 환자 정보를 제시하지 않거나, 체크리스트 개선 후 낙상 감소 성과만 설명한다."
          ]
        }
      }
    }
  ]
}
